/* Brand Method footer FX — node-network background + 3D spinning star logo.
   Extracted verbatim from brandmethod_site_v62.html. Requires three.min.js. */

/* sci-fi footer node network */
(function(){
  var cv=document.querySelector('.footer-fx'); if(!cv) return;
  var ctx=cv.getContext('2d'); var ft=cv.parentElement;
  var W=0,H=0,DPR=1, mouse={x:-9999,y:-9999,active:false}, nodes=[], raf=null;
  function build(){nodes=[];var count=Math.round(Math.min(66,Math.max(30,W*H/24000)));for(var i=0;i<count;i++){nodes.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-0.5)*0.22,vy:(Math.random()-0.5)*0.22});}}
  function resize(){DPR=Math.min(2,window.devicePixelRatio||1);W=ft.clientWidth;H=ft.clientHeight;cv.width=W*DPR;cv.height=H*DPR;cv.style.width=W+'px';cv.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);build();}
  resize(); window.addEventListener('resize',resize,{passive:true});
  ft.addEventListener('mousemove',function(e){var r=ft.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top;mouse.active=true;});
  ft.addEventListener('mouseleave',function(){mouse.active=false;});
  var LINK=128, MLINK=200;
  function draw(){
    ctx.clearRect(0,0,W,H);
    for(var i=0;i<nodes.length;i++){var n=nodes[i];n.x+=n.vx;n.y+=n.vy;
      if(n.x<0){n.x=0;n.vx*=-1;} if(n.x>W){n.x=W;n.vx*=-1;} if(n.y<0){n.y=0;n.vy*=-1;} if(n.y>H){n.y=H;n.vy*=-1;}
      if(mouse.active){var dx=n.x-mouse.x,dy=n.y-mouse.y,d=Math.sqrt(dx*dx+dy*dy)||1;if(d<150){var f=(150-d)/150;n.x+=dx/d*f*0.9;n.y+=dy/d*f*0.9;}}
    }
    for(var a=0;a<nodes.length;a++){
      for(var b=a+1;b<nodes.length;b++){
        var dx=nodes[a].x-nodes[b].x,dy=nodes[a].y-nodes[b].y,d=Math.sqrt(dx*dx+dy*dy);
        if(d<LINK){ctx.strokeStyle='rgba(255,255,255,'+(0.15*(1-d/LINK)).toFixed(3)+')';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(nodes[a].x,nodes[a].y);ctx.lineTo(nodes[b].x,nodes[b].y);ctx.stroke();}
      }
      if(mouse.active){var mx=nodes[a].x-mouse.x,my=nodes[a].y-mouse.y,md=Math.sqrt(mx*mx+my*my);
        if(md<MLINK){ctx.strokeStyle='rgba(255,255,255,'+(0.32*(1-md/MLINK)).toFixed(3)+')';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(nodes[a].x,nodes[a].y);ctx.lineTo(mouse.x,mouse.y);ctx.stroke();}}
    }
    for(var i=0;i<nodes.length;i++){ctx.fillStyle='rgba(255,255,255,0.5)';ctx.beginPath();ctx.arc(nodes[i].x,nodes[i].y,1.4,0,6.283);ctx.fill();}
    if(mouse.active){ctx.fillStyle='rgba(255,255,255,0.92)';ctx.beginPath();ctx.arc(mouse.x,mouse.y,2.6,0,6.283);ctx.fill();}
    raf=requestAnimationFrame(draw);
  }
  var io=new IntersectionObserver(function(en){if(en[0].isIntersecting){if(!raf)draw();}else if(raf){cancelAnimationFrame(raf);raf=null;}},{threshold:0});
  io.observe(ft);
})();

var LOGO_NOSTAR="data:image/png;base64,";
var UP2=[[0.0000,1.0000],[0.1294,0.4830],[0.5000,0.8660],[0.3536,0.3536],[0.8660,0.5000],[0.4830,0.1294],[1.0000,0.0000],[0.4830,-0.1294],[0.8660,-0.5000],[0.3536,-0.3536],[0.5000,-0.8660],[0.1294,-0.4830],[0.0000,-1.0000],[-0.1294,-0.4830],[-0.5000,-0.8660],[-0.3536,-0.3536],[-0.8660,-0.5000],[-0.4830,-0.1294],[-1.0000,-0.0000],[-0.4830,0.1294],[-0.8660,0.5000],[-0.3536,0.3536],[-0.5000,0.8660],[-0.1294,0.4830]];
/* ===== BrandMethod star :: soft single light wipe + flywheel hold ===== */
document.getElementById('bmWordmark').src = LOGO_NOSTAR;

/* the light wipe is clipped to the wordmark's own letterforms */
var sheenEl = document.getElementById('bmSheen');
sheenEl.style.webkitMaskImage = 'url(' + LOGO_NOSTAR + ')';
sheenEl.style.maskImage = 'url(' + LOGO_NOSTAR + ')';
sheenEl.addEventListener('animationend', function(){ sheenEl.classList.remove('go'); });
function wipe(){ sheenEl.classList.remove('go'); void sheenEl.offsetWidth; sheenEl.classList.add('go'); }

/* ---- tuning knob ---- */
var SPIN_SECONDS = 46;          // seconds / rev (studio default 40)
var ROT0 = 0.279;
var OE   = 3 * Math.PI / 180;
var MESH_SCALE = 0.64;
var DEPTH = 0.020;

/* ---- studio constants ---- */
var FACE = 0xffffff, SIDE = 0xdadada, TAU = Math.PI * 2;
var Q = [0.941393, 0.043777, 0.067454, 0.327587];
var qTilt = new THREE.Quaternion(Q[0], Q[1], Q[2], Q[3]);
var REDUCED = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function makeGeo(pts, depth){
  var sh = new THREE.Shape();
  pts.forEach(function(p, i){ i === 0 ? sh.moveTo(p[0], p[1]) : sh.lineTo(p[0], p[1]); });
  sh.closePath();
  var g = new THREE.ExtrudeGeometry(sh, {depth:depth, bevelEnabled:false, steps:1});
  g.center();
  return g;
}

var canvas = document.getElementById('bmCanvas');
var renderer = new THREE.WebGLRenderer({canvas:canvas, antialias:true, alpha:true});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));

var mats = [new THREE.MeshBasicMaterial({color:FACE, side:THREE.DoubleSide}),
            new THREE.MeshBasicMaterial({color:SIDE, side:THREE.DoubleSide})];
var scene = new THREE.Scene(), grp = new THREE.Group();
var mesh = new THREE.Mesh(makeGeo(UP2, DEPTH), mats);
mesh.scale.setScalar(MESH_SCALE);
grp.add(mesh); scene.add(grp);
var cam = new THREE.PerspectiveCamera(44, 1, 0.01, 100);

/* fixed studio overlay lens */
cam.up.set(0.13917, 0.99027, 0);
cam.position.set(0, -0.05 - Math.sin(OE) * 1.95, Math.cos(OE) * 1.95);
cam.lookAt(0, -0.05, 0);
cam.aspect = 1; cam.updateProjectionMatrix();

function sizeCanvas(){
  var r = canvas.getBoundingClientRect();
  if (r.width < 2) return;
  renderer.setSize(r.width, r.height, false);
}
window.addEventListener('resize', sizeCanvas);
document.getElementById('bmWordmark').addEventListener('load', sizeCanvas);

/* ---- hover ---- */
var starEl = document.getElementById('bmStar');
var hovT = 0, base = 1;
var sp = 0, sv = 0, K = 26, C = 5.2;

starEl.addEventListener('pointerenter', function(){ hovT = 1; wipe(); sv += 0.55; });
starEl.addEventListener('pointerleave', function(){ hovT = 0; sv += 0.34; });

function rev(s){ return TAU / (s * 1000); }

var phase = ROT0, last = null, booted = false;
function loop(t){
  if (last === null) last = t;
  var dt = t - last; last = t;
  var ds = dt / 1000;

  base += ((hovT ? 0 : 1) - base) * 0.045;      // hold: stop on hover, drift back on leave
  sv += (-K * sp - C * sv) * ds;                // settle spring (overshoot on enter/leave)
  sp += sv * ds;

  phase += (REDUCED ? 0 : dt * rev(SPIN_SECONDS) * base);
  grp.quaternion.copy(qTilt);
  mesh.rotation.z = phase + sp;

  if (!booted){ sizeCanvas(); booted = true; }
  if(window.__bmVis!==false){renderer.render(scene, cam);}
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
window.__bmReady = true;
try{var __io=new IntersectionObserver(function(es){window.__bmVis=es[0].isIntersecting;},{rootMargin:'120px'});__io.observe(document.querySelector('.bm-logo'));}catch(e){}
